        ['Write a Python function for binary search that returns the index of a target in a sorted list, or -1 if not found.', ['low/high', 'Loop', 'mid calculation', 'Three cases', 'Return -1'], 'def binary_search(items, target):
    low, high = 0, len(items) - 1
