        ['Write a Python function that performs a bubble sort on a list.', ['Outer loop', 'Inner loop', 'Compare neighbours', 'Swap', 'Early exit'], 'def bubble_sort(items):
    n = len(items)
    for i in range(n - 1):
        swapped = False
        for j in range(n - 1 - i):
            if items[j] > items[j + 1]:
                items[j], items[j + 1] = items[j + 1], items[j]
                swapped = True
        if not swapped:
            break
    return items', 'Compare your answer with the model answer and tick off the points you made.', 3, 'theory', 6],
